import {chapters,beats,clamp,smooth} from './story.js';
import {photos} from './photos.js';
import {Atmosphere} from './audio.js';
const $=s=>document.querySelector(s),narration=$('#narration'),rail=$('#chapters'),list=$('#chapter-list');
let progress=0,target=0,currentChapter=-1,world=null,fallback=false,last=performance.now(),elapsed=0,memoryIndex=0,lastMemoryGroup=-1;
let gentle=matchMedia('(prefers-reduced-motion: reduce)').matches;
try{const preference=localStorage.getItem('es-gentle-motion');if(preference!==null)gentle=preference==='true'}catch{}
const beatElements=beats.map((b,i)=>{const el=document.createElement('article');el.className=`story-beat ${b.cls}`;el.innerHTML=b.html;el.setAttribute('aria-label',b.html.replace(/<[^>]*>/g,' ').replace(/\s+/g,' '));el.setAttribute('aria-hidden','true');el.inert=true;narration.appendChild(el);return el});
function goto(p){window.scrollTo({top:p*(document.documentElement.scrollHeight-innerHeight),behavior:gentle?'instant':'smooth'})}
const dots=chapters.map((c,i)=>{const dot=document.createElement('button');dot.className='chapter-dot';dot.setAttribute('aria-label',`${c.roman}: ${c.name}`);dot.innerHTML=`<span class="tip">${c.name}</span>`;dot.onclick=()=>goto(c.at+.012);rail.appendChild(dot);const li=document.createElement('li'),b=document.createElement('button');b.innerHTML=`<span>${c.roman}</span>${c.name}`;b.onclick=()=>{closeDialog($('#chapters-dialog'));goto(c.at+.012)};li.appendChild(b);list.appendChild(li);return dot});
$('.monogram').onclick=e=>{e.preventDefault();goto(0)};$('#replay').onclick=()=>goto(0);
function openDialog(d){d.showModal();document.body.style.overflow='hidden'}function closeDialog(d){d.close();document.body.style.overflow=''}
for(const d of document.querySelectorAll('dialog')){d.querySelector('.close-dialog').onclick=()=>closeDialog(d);d.addEventListener('close',()=>{document.body.style.overflow=''});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})}
$('#chapter-menu').onclick=()=>openDialog($('#chapters-dialog'));
function showPhoto(index,open=true){memoryIndex=(index+photos.length)%photos.length;const p=photos[memoryIndex];$('#large-photo').src=p.src;$('#large-photo').alt=p.alt;$('#photo-caption').textContent=p.caption;$('#photo-count').textContent=`${String(memoryIndex+1).padStart(2,'0')} / ${photos.length}`;if(open&&!$('#memory-dialog').open)openDialog($('#memory-dialog'))}
$('#previous-photo').onclick=()=>showPhoto(memoryIndex-1,false);$('#next-photo').onclick=()=>showPhoto(memoryIndex+1,false);$('#memory-dialog').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();showPhoto(memoryIndex-1,false)}if(e.key==='ArrowRight'){e.preventDefault();showPhoto(memoryIndex+1,false)}});
const toggle=$('#motion-toggle');function setMotion(){toggle.textContent=gentle?'Gentler motion is on':'Use gentler motion';toggle.setAttribute('aria-pressed',String(gentle))}setMotion();toggle.onclick=()=>{gentle=!gentle;setMotion();try{localStorage.setItem('es-gentle-motion',String(gentle))}catch{}};
const audio=new Atmosphere();$('#sound').onclick=async()=>{try{const enabled=await audio.toggle();$('#sound').setAttribute('aria-pressed',String(enabled));$('#sound').setAttribute('aria-label',enabled?'Turn off music':'Turn on music');$('#sound-label').textContent=enabled?'SOUND ON':'SOUND OFF'}catch{$('#sound-label').textContent='AUDIO UNAVAILABLE';$('#sound').disabled=true}};
function readScroll(){target=clamp(scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight))}addEventListener('scroll',readScroll,{passive:true});addEventListener('resize',readScroll);readScroll();progress=target;
let fallbackPhoto;function activateFallback(reason){if(fallback)return;fallback=true;document.body.classList.add('fallback');$('#world').style.display='none';fallbackPhoto=document.createElement('img');fallbackPhoto.className='fallback-photo';fallbackPhoto.alt='';fallbackPhoto.style.display='none';document.body.appendChild(fallbackPhoto);$('#status').textContent='A lighter version of the story is active on this device.';console.warn('Using the lighter story experience:',reason?.message||reason)}
import('./world.js').then(({createWorld})=>{try{world=createWorld($('#world'),showPhoto);world.renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();activateFallback('Graphics context lost')})}catch(e){activateFallback(e)}}).catch(activateFallback);
function updateNarration(p){let chapter=0;chapters.forEach((c,i)=>{if(p>=c.at)chapter=i});if(chapter!==currentChapter){currentChapter=chapter;const c=chapters[chapter];$('#chapter-number').textContent=c.roman;$('#chapter-name').textContent=c.name.toUpperCase();$('#progress-label').textContent=`${String(chapter+1).padStart(2,'0')} / 10`;$('#scroll-label').textContent=chapter===0?'SCROLL TO BEGIN':chapter===9?'OUR STORY CONTINUES':'SCROLL TO CONTINUE';dots.forEach((d,i)=>{d.classList.toggle('active',i===chapter);if(i===chapter)d.setAttribute('aria-current','step');else d.removeAttribute('aria-current')});audio.fade(p)}
beats.forEach((b,i)=>{let a=b.from===0?1:smooth(b.from,b.from+.007,p);a*=1-smooth(b.to-.008,b.to,p);const el=beatElements[i],active=a>.025;el.style.opacity=a;el.classList.toggle('active',active);el.setAttribute('aria-hidden',String(!active));el.inert=!active;const y=gentle?0:(1-a)*14;const center=b.cls.includes('center');el.style.transform=`translate(${center?'-50%':'0'},calc(-50% + ${y}px))`;});
for(const line of document.querySelectorAll('.letter-line'))line.classList.toggle('shown',p>.848+Number(line.dataset.line)*.009);
$('#end-fade').style.opacity=smooth(.974,1,p)*.99;
const inGallery=p>.326&&p<.468,inGarden=p>.775&&p<.823;let group=inGallery?Math.min(4,Math.floor((p-.326)/.029)):(inGarden?5:-1);
if(group!==lastMemoryGroup){lastMemoryGroup=group;const box=$('#memory-prompts');box.innerHTML='';if(group>=0){const btn=document.createElement('button');btn.className='memory-chip';const idx=group===5?0:group*3;btn.innerHTML=`<span>◇</span> ${group===5?'A memory, close by':'MEMORIES '+String(idx+1).padStart(2,'0')+' — '+String(Math.min(idx+3,15)).padStart(2,'0')} <span style="margin-left:12px;margin-right:0">OPEN ↗</span>`;btn.onclick=()=>showPhoto(idx);box.appendChild(btn)}}
if(fallback){$('#matte').style.transform=gentle?'none':`scale(${1.05+p*.12}) translateX(${-p*2}%)`;let index=chapter===1?1:chapter===2?2:inGallery?Math.min(14,Math.floor((p-.326)/.142*15)):inGarden?0:-1;fallbackPhoto.style.display=index>=0?'block':'none';if(index>=0&&fallbackPhoto.dataset.id!==String(index)){fallbackPhoto.dataset.id=index;fallbackPhoto.src=photos[index].src;fallbackPhoto.alt=photos[index].alt;fallbackPhoto.onclick=()=>showPhoto(index)}}}
function loop(now){const dt=Math.min((now-last)/1000,.06);last=now;if(!document.hidden){elapsed+=dt;progress+= (target-progress)*(gentle?1:1-Math.exp(-dt*8));if(Math.abs(target-progress)<.000001)progress=target;updateNarration(progress);if(world&&!fallback){try{world.update(progress,elapsed,gentle,dt)}catch(e){activateFallback(e)}}}requestAnimationFrame(loop)}updateNarration(progress);requestAnimationFrame(loop);
